INSERT OR REPLACE INTO cards (id, name, name_cn, name_jp, type, race, attribute, level, atk, def, desc_cn) VALUES
(23740893, 'Yosenju Kodam', '妖仙兽 木魅', '妖仙獣 木魅', 'Effect Monster', 'Beast-Warrior', 'WIND', 1, NULL, NULL, '「妖仙兽 木魅」的①的效果1回合只能使用1次。 ①：把这张卡解放，以自己场上1张「修验的妖社」为对象才能发动。给那张卡放置3个妖仙指示物。 ②：自己主要阶段把墓地的这张卡除外才能发动。这个回合，自己在通常召唤外加上只有1次，自己主要阶段可以把1只「妖仙兽」怪兽召唤。'),
(49249907, 'Yosenju Magat', '妖仙兽 凶旋岚', '妖仙獣 凶旋嵐', 'Effect Monster', 'Beast', 'WIND', 6, 2000, 100, '①：这张卡召唤成功的场合才能发动。从卡组把「妖仙兽 凶旋岚」以外的1只「妖仙兽」怪兽特殊召唤。 ②：这张卡特殊召唤的回合的结束阶段发动。这张卡回到持有者手卡。'),
(39853199, 'Yosenju Misak', '妖仙兽 阎魔巳裂', '妖仙獣 閻魔巳裂', 'Effect Monster', 'Beast', 'WIND', 6, 2300, 200, '①：这张卡和风属性以外的表侧表示怪兽进行战斗的伤害步骤开始时才能发动。那只怪兽破坏。 ②：这张卡灵摆召唤成功时，以对方场上1张卡为对象才能发动。那张卡破坏。 ③：这张卡特殊召唤的回合的结束阶段发动。这张卡回到持有者手卡。'),
(61884774, 'Yosenju Oroshi Channeling', '妖仙兽的神颪', '妖仙獣の神颪', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '①：自己场上没有怪兽存在的场合，可以从以下效果选择1个发动。这张卡的发动后，直到回合结束时自己不是「妖仙兽」怪兽不能特殊召唤。 ●从卡组把1只5星以上的「妖仙兽」怪兽加入手卡。 ●从卡组选「妖仙兽 左镰神柱」「妖仙兽 右镰神柱」各1张在自己的灵摆区域放置。这个效果在灵摆区域放置的卡在下次的对方结束阶段破坏。'),
(69838592, 'Yosenju Oyam', '妖仙兽 大幽谷响', '妖仙獣 大幽谷響', 'Effect Monster', 'Beast', 'WIND', 6, -1, -1, '「妖仙兽 大幽谷响」的①的效果1回合只能使用1次。 ①：对方怪兽的直接攻击宣言时从手卡把「妖仙兽 大幽谷响」以外的1只「妖仙兽」怪兽送去墓地才能发动。这张卡从手卡特殊召唤。 ②：这张卡和对方怪兽进行战斗的伤害步骤开始时才能发动。这张卡的攻击力·守备力直到回合结束时变成和进行战斗的对方怪兽的原本攻击力相同。 ③：这张卡被战斗破坏送去墓地时才能发动。从卡组把1张「妖仙兽」卡加入手卡。'),
(58981727, 'Yosenju Sabu', '妖仙兽 侍郎风', '妖仙獣 侍郎風', 'Effect Monster', 'Beast-Warrior', 'WIND', 4, 1700, 400, '这个卡名的①②的效果1回合各能使用1次。 ①：自己场上有其他的「妖仙兽」卡存在，这张卡召唤成功的场合才能发动。从卡组把1只「妖仙兽」灵摆怪兽加入手卡。 ②：以自己场上1张「妖仙兽」卡为对象才能发动。从卡组把1张「妖仙乡的眩晕风」或者「妖仙大旋风」在自己的魔法与陷阱区域表侧表示放置，作为对象的卡回到持有者卡组。 ③：这张卡召唤的回合的结束阶段发动。这张卡回到持有者手卡。'),
(65025250, 'Yosenju Shinchu L', '妖仙兽 左镰神柱', '妖仙獣 左鎌神柱', 'Pendulum Effect Monster', 'Rock', 'WIND', 4, NULL, 2100, '①：这张卡召唤成功的场合发动。这张卡变成守备表示。 ②：只要这张卡在怪兽区域存在，对方不能把这张卡以外的自己场上的「妖仙兽」怪兽作为效果的对象。'),
(91420254, 'Yosenju Shinchu R', '妖仙兽 右镰神柱', '妖仙獣 右鎌神柱', 'Pendulum Effect Monster', 'Rock', 'WIND', 4, NULL, 2100, '①：这张卡召唤成功的场合发动。这张卡变成守备表示。 ②：只要这张卡在怪兽区域存在，对方不能把其他的「妖仙兽」怪兽作为攻击对象。'),
(25244515, 'Yosenju Tsujik', '妖仙兽 辻斩风', '妖仙獣 辻斬風', 'Effect Monster', 'Beast-Warrior', 'WIND', 4, 1000, NULL, '「妖仙兽 辻斩风」的①②的效果1回合各能使用1次。 ①：自己的「妖仙兽」怪兽和对方怪兽进行战斗的从伤害步骤开始时到伤害计算前，把这张卡从手卡丢弃才能发动。那只自己怪兽的攻击力直到回合结束时上升1000。 ②：以场上1只「妖仙兽」怪兽为对象才能发动。那只怪兽的攻击力直到回合结束时上升1000。 ③：这张卡召唤的回合的结束阶段发动。这张卡回到持有者手卡。'),
(54880296, 'Yosenju Wind Worship', '妖仙兽的风祀', '妖仙獣の風祀り', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：自己场上有「妖仙兽」怪兽卡3种类以上存在的场合才能发动。自己场上的「妖仙兽」怪兽卡全部回到持有者手卡。那之后，自己可以直到手卡变成5张为止从卡组抽卡。'),
(54903668, 'Yosenjus'' Secret Move', '妖仙兽的秘技', '妖仙獣の秘技', 'Trap Card', 'Counter', NULL, NULL, NULL, NULL, '①：自己场上有「妖仙兽」卡存在，自己的怪兽区域没有「妖仙兽」怪兽以外的表侧表示怪兽存在的场合，怪兽的效果·魔法·陷阱卡发动时才能发动。那个发动无效并破坏。'),
(10612222, 'Yosenjus'' Sword Sting', '妖仙兽的居太刀风', '妖仙獣の居太刀風', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：自己场上没有怪兽存在的场合，从手卡把最多2只卡名不同的「妖仙兽」怪兽给对方观看，以给人观看的数量的对方场上的表侧表示的卡为对象才能发动。那些卡回到持有者手卡。'),
(32056070, 'You and A.I.', '友爱-艾-', 'ユウ－Ai－', 'Spell Card', 'Continuous', NULL, NULL, NULL, NULL, '①：原本攻击力是2300的电子界族怪兽特殊召唤的场合，可以从那属性的以下效果选择1个发动。「友情-真“艾”-」的以下效果每1个属性在1回合只能选择1次。 ●地·水：选场上1只表侧表示怪兽，那个攻击力直到回合结束时变成一半。 ●风·光：选场上1张表侧表示的卡，那个效果直到回合结束时无效。 ●炎·暗：在自己场上把1只「@火灵天星衍生物」（电子界族·暗·1星·攻/守0）特殊召唤。'),
(88346805, 'You''re Finished', '斩余番长', '斬リ番', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '①：卡的效果10次以上发动的回合才能把这张卡发动。发动后变成效果怪兽（电子界族·暗·10星·攻/守3000）在怪兽区域特殊召唤（也当作陷阱卡使用）。这个效果特殊召唤的这张卡在自己结束阶段在自己的魔法与陷阱区域盖放。 ②：1回合1次，这张卡在怪兽区域存在，对方把卡的效果发动时才能发动。对方场上的卡全部破坏。那之后，这张卡在自己的魔法与陷阱区域盖放。'),
(10312660, 'You''re in Danger!', '未界域之盛情欢待', '未界域の歓待', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：从卡组把「未界域」怪兽3种类给对方观看，对方从那之中随机选1只。那1只怪兽在自己场上特殊召唤，剩下的怪兽回到卡组。这个效果特殊召唤的怪兽在结束阶段破坏。'),
(33393090, 'Yowie', '幽威', 'ヨーウィー', 'Effect Monster', 'Reptile', 'EARTH', 3, 500, 500, '这个卡名的效果在决斗中只能使用1次，这个效果发动的回合，自己只能有1次把怪兽特殊召唤。 ①：只让这张卡1只召唤·反转召唤·特殊召唤成功的场合才能发动。下次的对方抽卡阶段跳过。'),
(81332143, 'Yu-Jo Friendship', '友情 YU-JYO', '友情 YU－JYO', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '①：向对方玩家提出握手。对方答应握手的场合，双方基本分变成双方基本分合计数值的一半。自己手卡有「团结 UNITY」的场合，可以把那张卡给对方观看。那个场合，双方握手，这张卡的效果适用。'),
(78371393, 'Yubel', '尤贝尔', 'ユベル', 'Effect Monster', 'Fiend', 'DARK', 10, NULL, NULL, '①：这张卡不会被战斗破坏，这张卡的战斗发生的对自己的战斗伤害变成0。 ②：攻击表示的这张卡被选择作为攻击对象的场合，那次伤害计算前发动。给与对方攻击怪兽的攻击力数值的伤害。 ③：自己结束阶段发动。自己场上1只其他怪兽解放或这张卡破坏。 ④：这个③的效果以外让这张卡被破坏时才能发动。从自己的手卡·卡组·墓地把1只「于贝尔-被憎恶的骑士」特殊召唤。'),
(4779091, 'Yubel - Terror Incarnate', '尤贝尔－“忌避骑士”', 'ユベル－Das Abscheulich Ritter', 'Effect Monster', 'Fiend', 'DARK', 11, NULL, NULL, '这张卡不能通常召唤，用「于贝尔」的效果才能特殊召唤。 ①：这张卡不会被战斗破坏，这张卡的战斗发生的对自己的战斗伤害变成0。 ②：攻击表示的这张卡被选择作为攻击对象的场合，那次伤害计算前发动。给与对方攻击怪兽的攻击力数值的伤害。 ③：自己结束阶段发动。场上的其他怪兽全部破坏。 ④：表侧表示的这张卡从场上离开时才能发动。从自己的手卡·卡组·墓地把1只「于贝尔-极度悲伤的魔龙」特殊召唤。'),
(47172959, 'Yubel - The Loving Defender Forever', '尤贝尔－“永恒爱守”', 'ユベル－Das Ewig Liebe Wächter', 'Fusion Monster', 'Fiend', 'DARK', 12, NULL, NULL, '「于贝尔」怪兽＋场上的效果怪兽1只以上 这个卡名的①的效果1回合只能使用1次。 ①：这张卡融合召唤的场合才能发动。给与对方作为这张卡的融合素材的怪兽数量×500伤害。 ②：这张卡不会被战斗·效果破坏，这张卡的战斗发生的对自己的战斗伤害变成0。 ③：这张卡和对方怪兽进行战斗的伤害步骤结束时发动。给与对方那只对方怪兽的攻击力数值的伤害，那只怪兽除外。'),
(31764700, 'Yubel - The Ultimate Nightmare', '尤贝尔－“悲狂之龙”', 'ユベル－Das Extremer Traurig Drachen', 'Effect Monster', 'Fiend', 'DARK', 12, NULL, NULL, '这张卡不能通常召唤，用「于贝尔-被憎恶的骑士」的效果才能特殊召唤。 ①：这张卡不会被战斗破坏，这张卡的战斗发生的对自己的战斗伤害变成0。 ②：攻击表示的这张卡在和对方怪兽进行战斗的伤害步骤结束时发动。给与对方那只对方怪兽的攻击力数值的伤害，那只怪兽破坏。'),
(72700231, 'Yuki-Musume, the Ice Mayakashi', '冰之魔妖－雪娘', '氷の魔妖－雪娘', 'Effect Monster', 'Zombie', 'WATER', 1, NULL, 1900, '这个卡名的①的效果1回合只能使用1次。 ①：这张卡在手卡·墓地存在，自己场上有「冰之魔妖-雪娘」以外的「魔妖」卡存在的场合才能发动。这张卡特殊召唤。那之后，从卡组把1只不死族怪兽送去墓地。 ②：只要这张卡在怪兽区域存在，自己不是「魔妖」怪兽不能从额外卡组特殊召唤。'),
(2645637, 'Yuki-Onna, the Absolute Zero Mayakashi', '零冰之魔妖－雪女', '零氷の魔妖－雪女', 'Link Monster', 'Zombie', 'WATER', NULL, 2900, NULL, '不死族怪兽2只以上 这个卡名的③的效果1回合可以使用最多2次。 ①：「零冰之魔妖-雪女」在自己场上只能有1只表侧表示存在。 ②：只要这张卡在怪兽区域存在，除外的状态发动的对方怪兽的效果无效化。 ③：从墓地有怪兽特殊召唤的场合或者墓地的怪兽的效果发动的场合，以这张卡以外的场上1只表侧表示怪兽为对象才能发动。那只怪兽的攻击力变成0，那个效果无效。'),
(66870733, 'Yuki-Onna, the Ice Mayakashi', '冰之魔妖－雪女', '氷の魔妖－雪女', 'Link Monster', 'Zombie', 'WATER', NULL, 1900, NULL, '「魔妖」怪兽2只 这个卡名的③的效果1回合只能使用1次。 ①：「冰之魔妖-雪女」在自己场上只能有1只表侧表示存在。 ②：只要这张卡所连接区有同调怪兽存在，对方不能选择这张卡作为攻击对象。 ③：这张卡在怪兽区域存在，自己的同调怪兽被战斗或者对方的效果破坏的场合，以场上1只表侧表示怪兽为对象才能发动。那只怪兽的攻击力·守备力直到回合结束时变成一半。'),
(36114945, 'Yuki-Onna, the Icicle Mayakashi', '垂冰之魔妖－雪女', '垂氷の魔妖－雪女', 'Link Monster', 'Zombie', 'WATER', NULL, 2400, NULL, '不死族怪兽2只以上 这个卡名的②③的效果1回合各能使用1次。 ①：「垂冰之魔妖-雪女」在自己场上只能有1只表侧表示存在。 ②：这张卡特殊召唤成功的场合，以对方场上1只效果怪兽为对象才能发动。那只怪兽的效果无效。 ③：把墓地的这张卡除外才能发动。从自己墓地的怪兽以及除外的自己怪兽之中选1只不死族同调怪兽特殊召唤。这个效果在对方回合也能发动。'),
(56870908, 'Yum☆Yum☆Yummys', '游蜜☆游蜜☆黯蜜滋', 'Yum☆Yum☆ヤミーズ', 'Spell Card', 'Continuous', NULL, NULL, NULL, NULL, '这个卡名的②③的效果1回合各能使用1次。 ①：每次自己场上有「味美喵」怪兽2只以上同时特殊召唤，自己回复500基本分，对方支付500基本分。 ②：支付500基本分，以包含「味美喵★点心抓取猫」的场上2只表侧表示怪兽为对象才能发动。那2只送去墓地，从额外卡组把1只「味美喵」同调怪兽当作同调召唤作特殊召唤。 ③：对方把效果发动的场合，支付100基本分才能发动。进行1只「味美喵」连接怪兽的连接召唤。'),
(65853758, 'Yummy★Redemption', '黯蜜★救赎', 'ヤミー★リデンプション', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '这个卡名的③的效果1回合只能使用1次。 ①：对方场上的怪兽的攻击力下降自己的场上·墓地的兽族·光属性怪兽数量×200。 ②：自己把兽族·光属性同调怪兽同调召唤的场合才能发动（同一连锁上最多1次）。自己抽1张。那之后，选自己1张手卡回到卡组最下面。 ③：把墓地的这张卡除外，以自己场上1只「味美喵」怪兽和对方场上1只怪兽为对象才能发动。那2只怪兽的控制权交换。'),
(30581601, 'Yummy★Snatchy', '黯蜜★史拿奇', 'ヤミー★スナッチー', 'Link Monster', 'Beast', 'LIGHT', NULL, 600, NULL, '4星以下的兽族·光属性怪兽1只 这个卡名的①的效果1回合只能使用1次。 ①：这张卡特殊召唤的场合才能发动。从手卡·卡组把1张「味美喵」场地魔法卡在自己场上表侧表示放置。这个回合，自己不能把连接3以上的连接怪兽连接召唤。 ②：自己·对方的主要阶段以及对方战斗阶段，支付100基本分才能发动（同一连锁上最多1次）。用包含「味美喵」怪兽的自己场上的怪兽为素材进行同调召唤。'),
(29369059, 'Yummy☆Surprise', '黯蜜☆惊喜', 'ヤミー☆サプライズ', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '①：可以从以下选择1个发动（这个卡名的以下效果1回合各能选择1次）。 ●以自己场上2只兽族·光属性怪兽和对方场上2张卡为对象才能发动。那些卡回到手卡。 ●从自己的手卡·墓地把1只「味美喵」怪兽特殊召唤。那只怪兽在这个回合不能直接攻击。 ●从自己的场上（表侧表示）·墓地让1张场地魔法卡回到手卡。那之后，可以从手卡把1张「味美喵」场地魔法卡在自己场上表侧表示放置。'),
(93360904, 'Yummyusment★Acroquey', '黯蜜游乐★巨可口', 'ヤミーズメント★アクロッキー', 'Spell Card', 'Field', NULL, NULL, NULL, NULL, '这个卡名的①②③的效果1回合各能使用1次。 ①：自己把兽族·光属性同调怪兽同调召唤的场合，以对方场上1张卡为对象才能发动。那张卡破坏。 ②：自己场上的表侧表示怪兽因对方的效果从场上离开的场合才能发动。从卡组把1只「味美喵」怪兽特殊召唤。 ③：这张卡在墓地存在的场合，以自己的墓地·除外状态的2只「味美喵」怪兽为对象才能发动。那些怪兽和这张卡用喜欢的顺序回到卡组下面。'),
(66975205, 'Yummyusment☆Mignon', '黯蜜游乐☆小可爱', 'ヤミーズメント☆ミニヨン', 'Spell Card', 'Field', NULL, NULL, NULL, NULL, '这个卡名的②③的效果1回合各能使用1次。 ①：自己场上的「味美喵」怪兽的攻击力上升场上的兽族·光属性怪兽数量×500。 ②：自己场上有连接1怪兽存在的场合，以自己墓地1只1星「味美喵」怪兽为对象才能发动。那只怪兽特殊召唤。 ③：这张卡在墓地存在的场合，以自己的墓地·除外状态的2只「味美喵」怪兽为对象才能发动。那些怪兽和这张卡用喜欢的顺序回到卡组下面。'),
(25119460, 'YZ-Tank Dragon', 'YZ－履带龙', 'YZ－キャタピラー・ドラゴン', 'Fusion Monster', 'Machine', 'LIGHT', 6, 2100, 2200, '「Y-龙头」＋「Z-金属履带」 把自己场上的上记卡除外的场合才能从额外卡组特殊召唤。这张卡不能作从墓地的特殊召唤。 ①：丢弃1张手卡，以对方场上1只里侧表示怪兽为对象才能发动。那只对方的里侧表示怪兽破坏。'),
(64500000, 'Z-Metal Tank', 'Z－金属履带', 'Z－メタル・キャタピラー', 'Union Effect Monster', 'Machine', 'LIGHT', 4, 1500, 1300, '①：1回合1次，可以把1个以下效果发动。 ●以自己场上1只「X-首领加农」或「Y-龙头」为对象，把这张卡当作装备魔法卡使用来装备。装备怪兽被战斗·效果破坏的场合，作为代替把这张卡破坏。 ●装备状态的这张卡特殊召唤。 ②：装备怪兽的攻击力·守备力上升600。'),
(62499965, 'Z-ONE', 'Z－ONE', 'Z－ONE', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '①：盖放的这张卡被破坏送去墓地的场合，以自己墓地1张永续魔法卡或者场地魔法卡为对象发动。那张卡加入手卡。'),
(33744268, 'Z-Zillion Tank', 'Z－无尽履带', 'Z－ジリオン・キャタピラー', 'Union Effect Monster', 'Machine', 'LIGHT', 4, 1500, 1300, '①：这张卡特殊召唤的场合才能发动。自己的除外状态的1只机械族·光属性·4星怪兽当作装备魔法卡使用给这张卡装备。这个回合，自己不是光属性怪兽不能从额外卡组特殊召唤。 ②：1回合1次，可以把1个以下效果发动。 ●以自己场上1只机械族怪兽为对象，把这张卡当作装备魔法卡使用来装备。装备怪兽被战斗·效果破坏的场合，作为代替把这张卡破坏。 ●装备状态的这张卡特殊召唤。'),
(87602890, 'Zaborg the Mega Monarch', '轰雷帝扎博尔格', '轟雷帝ザボルグ', 'Effect Monster', 'Thunder', 'LIGHT', 8, 2800, 1000, '这张卡可以把1只上级召唤的怪兽解放作上级召唤。 ①：这张卡上级召唤成功的场合，以场上1只怪兽为对象发动。那只怪兽破坏。破坏的怪兽是光属性的场合，双方各自从自己的额外卡组选那个原本的等级或者阶级数量的卡送去墓地。这张卡把光属性怪兽解放作上级召唤成功的场合，那个时候的效果加上以下效果。 ●送去墓地的对方的卡由自己来选。'),
(51945556, 'Zaborg the Thunder Monarch', '雷帝扎博尔格', '雷帝ザボルグ', 'Effect Monster', 'Thunder', 'LIGHT', 5, 2400, 1000, '①：这张卡上级召唤成功的场合，以场上1只怪兽为对象发动。那只怪兽破坏。'),
(40460013, 'Zalamander Catalyzer', '炎魔的触媒', '炎魔の触媒', 'Effect Monster', 'Fiend', 'FIRE', 4, 1600, 200, '这个卡名的①②的效果1回合各能使用1次。 ①：把手卡的这张卡和手卡1只恶魔族怪兽给对方观看才能发动。那2只之内的1只特殊召唤，另1只丢弃。 ②：这张卡在墓地存在的状态，自己的恶魔族怪兽的战斗让怪兽被破坏时才能发动。这张卡加入手卡。'),
(4891376, 'Zalen the Shackled Dragon', '锁缚龙 扎连', '鎖縛竜ザレン', 'Synchro Tuner Monster', 'Dragon', 'DARK', 7, 2800, 2100, '调整＋同调怪兽1只以上 这个卡名的②的效果1回合只能使用1次。 ①：把自己场上的这张卡作为同调素材的场合，可以把这张卡当作调整以外的怪兽使用。 ②：连锁卡的效果的发动让魔法·陷阱·怪兽的效果发动时，可以从以下效果选择1个发动。 ●那个效果无效并破坏。 ●那个效果连锁的卡的效果无效并破坏。'),
(30090452, 'Zanki', '铠武者 斩鬼', '鎧武者斬鬼', 'Normal Monster', 'Warrior', 'EARTH', 5, 1500, 1700, '喜好单挑，能抓住一瞬间的机会发动反击。'),
(97466438, 'Zany Zebra', '横条邪斑马', 'ヨコシマウマ', 'Pendulum Effect Monster', 'Beast', 'DARK', 2, NULL, 2000, '①：这张卡召唤·特殊召唤成功的场合，指定没有使用的主要怪兽区域或者魔法与陷阱区域1处才能发动。指定的区域在这只怪兽表侧表示存在期间不能使用。'),
(29951323, 'Zap Mustung', '放电枪野马', '放電ムスタンガン', 'Effect Monster', 'Thunder', 'LIGHT', 4, 1600, 1500, '这张卡不能通常召唤，在自己没有进行特殊召唤的自己主要阶段1，用卡的效果才能特殊召唤。 ①：这张卡1回合最多2次不会被战斗破坏。 ②：只要这张卡在怪兽区域存在，回合玩家只能有最多和那个回合攻击过的次数相同次数把怪兽特殊召唤。'),
(28929131, 'Zaphion, the Timelord', '时械神 亚法恩', '時械神ザフィオン', 'Effect Monster', 'Fairy', 'WATER', 10, NULL, NULL, '这张卡不能从卡组特殊召唤。 ①：自己场上没有怪兽存在的场合，这张卡可以不用解放作召唤。 ②：这张卡不会被战斗·效果破坏，这张卡的战斗发生的对自己的战斗伤害变成0。 ③：这张卡进行战斗的战斗阶段结束时发动。对方场上的魔法·陷阱卡全部回到卡组。 ④：这张卡从场上送去墓地的场合才能发动。自己从卡组抽1张。 ⑤：自己准备阶段发动。这张卡回到持有者卡组。'),
(92744676, 'Zapper Shrimp', '电磁虾', 'デンジエビ', 'Synchro Tuner Monster', 'Fish', 'LIGHT', 2, 1000, 1200, '调整＋调整以外的怪兽1只 这个卡名的①的效果1回合只能使用1次。 ①：这张卡特殊召唤的场合，从自己的手卡·场上把这张卡以外的1张卡送去墓地，以对方场上1张魔法·陷阱卡为对象才能发动。那张卡破坏。 ②：对方主要阶段才能发动（同一连锁上最多1次）。用包含这张卡的自己场上的怪兽为素材进行同调召唤。'),
(64230128, 'Zaralaam the Dark Palace', '暗黑神殿 扎拉拉暮', '暗黒神殿ザララーム', 'Spell Card', 'Field', NULL, NULL, NULL, NULL, '①：只要自己场上有把「光之圣剑 丹内尔」装备的怪兽存在，对方在战斗阶段不能把效果发动。 ②：1回合1次，自己的「勇者衍生物」战斗破坏对方怪兽时才能发动。给与对方那只对方怪兽的原本攻击力数值的伤害。 ③：这张卡的②的效果发动的回合的自己主要阶段才能发动1次。从自己的卡组·墓地选「暗黑神殿 扎拉拉姆」以外的1张有「勇者衍生物」的衍生物名记述的场地魔法卡加入手卡。'),
(10598400, 'Zarigun', '龙虾怪', 'ザリガン', 'Normal Monster', 'Aqua', 'WATER', 2, 600, 700, '由虾进化成的怪兽。用大钳子攻击对方的颈项。'),
(2815176, 'Zebufera, Vaalmonican Hallow Heathen', '华耳琴璃之神异－则步费岚', 'ヴァルモニカの神異－ゼブフェーラ', 'Link Monster', 'Fiend', 'LIGHT', NULL, 2500, NULL, '效果怪兽1只 这张卡的连接召唤若非自己的灵摆区域的恶魔族怪兽卡的响鸣指示物是3个以上的场合则不能进行，自己对「异响鸣之神异-风暴恶魔」1回合只能有1次特殊召唤。 ①：自己场上的卡被战斗·效果破坏的场合，可以作为代替把自己的灵摆区域3个响鸣指示物取除。 ②：对方回合1次，以自己的墓地·除外状态的1张「异响鸣」通常魔法·通常陷阱卡为对象才能发动。那张魔法·陷阱卡发动时的效果适用。'),
(35561352, 'Zefra Divine Strike', '神数的神击', 'セフィラの神撃', 'Trap Card', 'Counter', NULL, NULL, NULL, NULL, '①：怪兽的效果·魔法·陷阱卡发动时，从自己的额外卡组把1只表侧表示的「神数」怪兽除外才能发动。那个发动无效并破坏。'),
(85216896, 'Zefra Metaltron', '神数炼机圣 梅塔特隆', 'セフィラ・メタトロン', 'Link Monster', 'Wyrm', 'LIGHT', NULL, 2500, NULL, '从额外卡组特殊召唤的怪兽2只以上 这个卡名的①②的效果1回合各能使用1次。 ①：这张卡所连接区的从额外卡组特殊召唤的怪兽被战斗或者对方的效果破坏的场合才能发动。从自己墓地的怪兽以及自己的额外卡组的表侧表示的灵摆怪兽之中选1只怪兽加入手卡。 ②：以这张卡以外的自己以及对方场上的从额外卡组特殊召唤的怪兽各1只为对象才能发动。那2只怪兽直到结束阶段除外。'),
(5255013, 'Zefra Path', '神数的辉迹', 'セフィラの輝跡', 'Spell Card', 'Continuous', NULL, NULL, NULL, NULL, '①：自己的灵摆区域有2张「神数」卡存在，1和7的灵摆刻度适用中的场合才能把这张卡发动。自己场上有「神数」怪兽以外的怪兽存在的场合，那些怪兽全部回到持有者卡组。 ②：只要这张卡在魔法与陷阱区域存在，双方不是从手卡·额外卡组中不能把怪兽特殊召唤。 ③：只要自己的灵摆区域有卡存在，这张卡不会成为效果的对象，自己的灵摆区域的卡被破坏的场合这张卡破坏。'),
(74580251, 'Zefra Providence', '神数的神意', 'セフィラの神意', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '「神数的神意」在1回合只能发动1张。 ①：从卡组把「神数的神意」以外的1张「神数」卡加入手卡。 ②：自己场上的「神数」卡被破坏的场合，可以作为代替把墓地的这张卡除外。这个效果在这张卡送去墓地的回合不能使用。'),
(96073342, 'Zefra War', '神数的星战', 'セフィラの星戦', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '「神数的星战」在1回合只能发动1张。自己的灵摆区域有2张「神数」卡存在的场合，这张卡的发动从手卡也能用。 ①：以自己场上1张「神数」卡和对方场上1张卡为对象才能发动。那些卡破坏。'),
(29432356, 'Zefraath', '智天之神星龙', '智天の神星龍', 'Pendulum Effect Monster', 'Rock', 'EARTH', 11, 3450, 2950, '这张卡不能通常召唤。这张卡在额外卡组表侧表示存在，把包含「神数」怪兽3只以上的自己场上的怪兽全部解放的场合才能特殊召唤。 ①：这张卡特殊召唤成功的回合，自己在通常的灵摆召唤外加上只有1次，自己主要阶段可以把「神数」怪兽灵摆召唤。 ②：1回合1次，把自己场上1只怪兽解放才能发动。从卡组把1只「神数」怪兽特殊召唤。'),
(58990362, 'Zefraniu, Secret of the Yang Zing', '秘龙星－源质囚牛', '秘竜星－セフィラシウゴ', 'Pendulum Effect Monster', 'Wyrm', 'EARTH', 6, NULL, 2600, '这个卡名的怪兽效果1回合只能使用1次。 ①：这张卡灵摆召唤成功时或者自己的怪兽区域的这张卡被战斗·效果破坏时才能发动。从卡组把1张「龙星」魔法·陷阱卡或者「神数」魔法·陷阱卡加入手卡。'),
(84388461, 'Zefrasaber, Swordmaster of the Nekroz', '剑圣的影灵衣－源质军刀', '剣聖の影霊衣－セフィラセイバー', 'Pendulum Effect Monster', 'Spellcaster', 'WATER', 4, 1500, 800, '「剑圣之影灵衣-神数剑士」的怪兽效果1回合只能使用1次。 ①：把自己的手卡·场上的这张卡解放才能发动。等级合计直到变成和仪式召唤的怪兽相同为止，把自己的手卡·场上的怪兽解放，从手卡把1只「影灵衣」仪式怪兽仪式召唤。'),
(20773176, 'Zefraxa, Flame Beast of the Nekroz', '炎兽的影灵衣－源质艾格扎', '炎獣の影霊衣－セフィラエグザ', 'Pendulum Effect Monster', 'Dragon', 'FIRE', 5, 2000, 1000, '「炎兽之影灵衣-神数艾可萨」的怪兽效果1回合只能使用1次。 ①：这张卡在手卡·墓地存在，「炎兽之影灵衣-神数艾可萨」以外的自己的怪兽区域·灵摆区域的「影灵衣」卡或者「神数」卡被战斗·效果破坏的场合才能发动。这张卡特殊召唤。'),
(21495657, 'Zefraxi, Treasure of the Yang Zing', '宝龙星－源质负屃', '宝竜星－セフィラフウシ', 'Pendulum Effect Monster', 'Wyrm', 'EARTH', 3, 1500, NULL, '这个卡名的怪兽效果1回合只能使用1次。 ①：这张卡灵摆召唤或者从卡组的特殊召唤成功的场合，以「宝龙星-神数负屃」以外的自己场上1只「龙星」怪兽或者「神数」怪兽为对象才能发动。这个回合，那只表侧表示怪兽当作调整使用。这个效果发动过的这张卡从场上离开的场合回到持有者卡组最下面。'),
(74854609, 'Zekt Conversion', '虫装变换', 'ゼクト・コンバージョン', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '自己场上的名字带有「甲虫装机」的怪兽被选择作为攻击对象时才能发动。攻击对象怪兽当作装备卡使用给1只攻击怪兽装备。只要因这个效果被名字带有「甲虫装机」的怪兽装备中，自己得到那只装备怪兽的控制权。'),
(97946536, 'Zektrike Kou-ou', '虫装三轮车-红黄', 'ゼクトライク－紅黄', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名在规则上也当作「甲虫装机」卡使用。这个卡名的卡在1回合只能发动1张。 ①：可以从手卡以及自己场上的表侧表示的卡之中把1张「甲虫装机」卡送去墓地，从以下效果选择1个发动。 ●从卡组选1只「甲虫装机」怪兽特殊召唤或当作装备卡使用给自己场上1只「甲虫装机」怪兽装备。 ●从卡组选1张「甲虫装机」装备魔法卡给自己场上1只「甲虫装机」怪兽装备。'),
(22858242, 'Zeman the Ape King', '猿魔王 塞曼', '猿魔王ゼーマン', 'Synchro Monster', 'Beast', 'EARTH', 7, 2500, 1800, '暗属性调整＋调整以外的兽族怪兽1只 这张卡攻击的场合，对方直到伤害步骤结束时魔法·陷阱卡不能发动。对方怪兽的攻击宣言时，可以把自己的手卡或者场上1只怪兽送去墓地，让1只对方怪兽的攻击无效。'),
(83319610, 'Zenmaiday', '发条拧紧', '発条の巻き上げ', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '这张卡的①②的效果在同一连锁上不能发动。 ①：1回合1次，以自己场上1只机械族超量怪兽为对象才能发动。选自己的手卡·场上1只「发条」怪兽在作为对象的怪兽下面重叠作为超量素材。 ②：把魔法与陷阱区域的表侧表示的这张卡送去墓地，以自己场上1只「发条」超量怪兽为对象才能发动。比那只自己怪兽阶级高1阶的1只「发条」超量怪兽在那上面重叠当作超量召唤从额外卡组特殊召唤。'),
(61011311, 'Zenmailfunction', '上过度的发条', '巻きすぎた発条', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '选择自己墓地存在的1只名字带有「发条」的怪兽发动。选择的怪兽表侧守备表示特殊召唤。这个效果特殊召唤的怪兽的效果无效化，不能解放，也不能作为同调素材。'),
(91422370, 'Zenmailstrom', '螺旋式发条', '螺旋式発条', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '把自己场上1只攻击力1500以上的名字带有「发条」的怪兽解放发动。从手卡把1只名字带有「发条」的怪兽特殊召唤。那之后，可以把持有和这个效果特殊召唤的怪兽相同攻击力的1只名字带有「发条」的怪兽从卡组特殊召唤。'),
(29999161, 'Zenmairch', '发条回拧', '発条の巻き戻し', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '选择自己场上表侧表示存在的1只4星以下的名字带有「发条」的怪兽回到手卡，和回去的怪兽相同等级的1只名字带有「发条」的怪兽从手卡特殊召唤。'),
(76133574, 'Zep, Ruby of the Ghoti', '游魊之红玉 泽普', 'ゴーティスの紅玉ゼップ', 'Tuner Monster', 'Fish', 'WATER', 2, NULL, 1000, '这个卡名的①②③的效果1回合各能使用1次。 ①：把这张卡从手卡除外，以自己墓地1只鱼族怪兽为对象才能发动。那只怪兽除外。 ②：这张卡在对方回合被除外的场合才能发动。这张卡特殊召唤。 ③：这张卡特殊召唤的场合才能发动。用包含这张卡的自己场上的怪兽为素材进行1只鱼族同调怪兽的同调召唤。'),
(81756897, 'Zera Ritual', '杰拉的仪式', 'ゼラの儀式', 'Spell Card', 'Ritual', NULL, NULL, NULL, NULL, '召唤「杰拉」降临必要。场上和手卡加起来总共8颗星以上的怪兽作祭品。'),
(69123138, 'Zera the Mant', '杰拉', 'ゼラ', 'Ritual Monster', 'Fiend', 'DARK', 8, 2800, 2300, '「杰拉的仪式」降临。'),
(12171659, 'Zeradias, Herald of Heaven', '天空的使者 杰拉迪亚斯', '天空の使者 ゼラディアス', 'Effect Monster', 'Fairy', 'LIGHT', 4, 2100, 800, '①：把这张卡从手卡丢弃去墓地才能发动。从卡组把1张「天空的圣域」加入手卡。 ②：场上没有「天空的圣域」存在的场合这张卡破坏。'),
(87640391, 'Zereort Migrator', '冰候鸟', 'リオート・ミグラトリー', 'Effect Monster', 'Winged Beast', 'WATER', 5, 1000, 2200, '这个卡名的①②的效果1回合各能使用1次。 ①：这张卡在手卡存在，场上有水属性超量怪兽存在的场合才能发动。这张卡特殊召唤。 ②：自己主要阶段才能发动。自己场上1个超量素材取除。那之后，可以从自己的手卡·墓地把1只3·4星的水属性怪兽效果无效特殊召唤。这个回合，把这个效果特殊召唤的怪兽在水属性怪兽的超量召唤使用的场合，可以把那个等级当作5星使用。'),
(60162470, 'Zero Extra Link', '零型额外连接', 'ゼロ・エクストラリンク', 'Spell Card', 'Continuous', NULL, NULL, NULL, NULL, '以额外怪兽区域的连接怪兽的所互相连接区1只自己的连接怪兽为对象才能把这张卡发动。 ①：作为对象的怪兽的攻击力上升场上的连接怪兽数量×800。 ②：作为对象的怪兽作为素材让连接怪兽连接召唤的场合发动。那只连接怪兽的攻击力直到回合结束时上升这张卡的①的效果上升过的数值。 ③：作为对象的怪兽攻击的伤害计算后发动。这张卡破坏。'),
(17521642, 'Zero Force', '零之力', 'ゼロ・フォース', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '自己场上表侧表示存在的怪兽从游戏中除外时才能发动。场上表侧表示存在的全部怪兽的攻击力变成0。'),
(93816465, 'Zero Gardna', '零点守卫士', 'ゼロ・ガードナー', 'Effect Monster', 'Warrior', 'EARTH', 4, NULL, NULL, '把这张卡解放发动。这个回合自己怪兽不会被战斗破坏，和对方怪兽的战斗发生的对自己的战斗伤害变成0。这个效果在对方回合也能发动。'),
(83133491, 'Zero Gravity', '重力解除', '重力解除', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '①：场上的全部表侧表示怪兽的表示形式变更。'),
(93014827, 'Zero-Day Blaster', '零日冲击波', 'ゼロ・デイ・ブラスター', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '①：把自己场上1只暗属性连接怪兽解放，以那个连接标记数量的场上的卡为对象才能发动。那些卡破坏。'),
(30562585, 'ZERO-MAX', '零-最大', 'ZERO－MAX', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '自己手卡是0张的场合，选择自己墓地存在的1只名字带有「永火」的怪兽才能发动。选择的怪兽特殊召唤，持有比特殊召唤的怪兽的攻击力低的攻击力的场上表侧表示存在的怪兽全部破坏。这张卡发动的回合，自己不能进行战斗阶段。'),
(85446833, 'Zerozerock', '零零封锁', 'ゼロゼロック', 'Spell Card', 'Continuous', NULL, NULL, NULL, NULL, '只要这张卡在场上存在，对方不能选择表侧攻击表示存在的攻击力0的怪兽作为攻击对象。'),
(17739335, 'Zerrziel, Ruler of the Evil Eyed', '咒眼之王 泽拉凯尔', '呪眼の王 ザラキエル', 'Link Monster', 'Fiend', 'DARK', NULL, 2600, NULL, '「咒眼」怪兽2只以上 这个卡名的②的效果1回合只能使用1次。 ①：攻击力2600以上的怪兽为素材作连接召唤的这张卡在同1次的战斗阶段中可以作2次攻击。 ②：这张卡有「太阴之咒眼」装备的场合，以对方场上1张卡为对象才能发动。那张卡破坏。这个效果在对方回合也能发动。 ③：这张卡的②的效果发动的场合，下次的准备阶段发动。选这张卡所连接区1只效果怪兽，那个效果无效。'),
(64382839, 'Zeta Reticulant', '网罟座泽塔星人', 'ゼータ・レティキュラント', 'Effect Monster', 'Fairy', 'DARK', 7, 2400, 2100, '①：这张卡在墓地存在，每次对方场上的怪兽被除外发动。在自己场上把1只「地外生命衍生物」（恶魔族·暗·2星·攻/守500）特殊召唤。 ②：这张卡可以把自己场上1只「地外生命衍生物」解放，从手卡特殊召唤。'),
(31712840, 'Zexal Alliance', 'ZEXAL结盟', 'ゼアル・アライアンス', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '①：自己场上的表侧表示的超量怪兽被战斗或者对方的效果破坏的场合，把基本分支付到变成10基本分才能发动。从自己墓地选1只「希望皇 霍普」怪兽特殊召唤，从卡组选1张卡在卡组最上面放置。这个效果特殊召唤的怪兽攻击力变成2倍，不会被效果破坏，不会被和「No.」怪兽以外的怪兽的战斗破坏。'),
(95664204, 'Zexal Catapult', 'ZEXAL弹射器', 'ゼアル・カタパルト', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的①②的效果1回合各能使用1次。 ①：从手卡把1只「异热同心武器」怪兽或者「异热同心从者」怪兽特殊召唤。自己场上有「希望皇 霍普」怪兽存在的场合，可以再把自己场上的全部怪兽的等级变成4星或者5星。 ②：把1只「异热同心武器」怪兽或者「异热同心从者」怪兽和这张卡从自己墓地除外，以对方场上1张卡为对象才能发动。那张卡破坏。这个效果在这张卡送去墓地的回合不能发动。'),
(62623659, 'Zexal Construction', 'ZEXAL构建', 'ゼアル・コンストラクション', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：把1张手卡给对方观看，从卡组把以下的卡之内任意1张加入手卡。那之后，给人观看的卡回到卡组。 ●「异热同心武器」怪兽 ●「异热同心从者」怪兽 ●「异热同心」魔法·陷阱卡 ●「升阶魔法」魔法卡 ●「降阶魔法」魔法卡'),
(4017398, 'Zexal Entrust', 'ZEXAL托付', 'ゼアル・エントラスト', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的①②的效果1回合各能使用1次。 ①：以自己墓地的「希望皇 霍普」、「异热同心武器」、「异热同心从者」怪兽之内任意1只为对象才能发动。那只怪兽加入手卡或特殊召唤。 ②：自己基本分比对方少2000以上的场合，把墓地的这张卡除外，以「异热同心信托」以外的自己墓地1张「异热同心」魔法·陷阱卡为对象才能发动。那张卡加入手卡。这个效果在这张卡送去墓地的回合不能发动。'),
(95856586, 'Zexal Field', 'ZEXAL领域', 'ゼアル・フィールド', 'Spell Card', 'Field', NULL, NULL, NULL, NULL, '这个卡名的②的效果1回合只能使用1次。 ①：对方不能对应以自己场上的超量怪兽为对象的自己的卡的效果的发动把魔法·陷阱·怪兽的效果发动。 ②：自己场上有超量怪兽特殊召唤的场合，以那1只怪兽为对象才能发动。从自己的额外卡组·墓地选1只超量怪兽在作为对象的怪兽下面重叠作为超量素材。 ③：自己抽卡阶段的抽卡前才能发动。从卡组选1张「闪光抽卡」在卡组最上面放置。'),
(24311372, 'Zoa', '戴比鲁佐亚', 'デビルゾア', 'Normal Monster', 'Fiend', 'DARK', 7, 2600, 1900, '据说会通过金属化来发挥真正力量的怪兽。'),
(53753697, 'Zoa the Fiendish Beast', '恶之魔兽 戴比鲁佐亚', '悪魔獣デビルゾア', 'Effect Monster', 'Fiend', 'DARK', 7, 2600, 1900, '这个卡名的②③的效果1回合各能使用1次。 ①：对方场上有怪兽存在的场合，这张卡可以不用解放作召唤。 ②：这张卡在手卡存在的场合才能发动。这张卡守备表示特殊召唤。自己墓地没有「金属化·强化反射装甲」存在的场合，再让对方可以从自身手卡把1只怪兽特殊召唤。 ③：自己主要阶段才能发动。从卡组把1张「金属化」陷阱卡在自己场上盖放。'),
(675319, 'Zodiac Sign', '十二阵 星宫', 'ゾディアックS', 'Spell Card', 'Field', NULL, NULL, NULL, NULL, '①：自己场上的「十二兽」怪兽的攻击力·守备力上升300。 ②：只要这张卡在场地区域存在，对方不能选择除自己场上的攻击力最高的兽战士族怪兽以外的自己的兽战士族怪兽作为攻击对象。 ③：1回合1次，自己场上的「十二兽」怪兽被效果破坏的场合，可以作为那1只「十二兽」怪兽的代替而把自己的手卡·场上1只怪兽破坏。'),
(35998832, 'Zohah, the Ogdoadic Boundless', '溟界之漠－浊哈', '溟界の漠－ゾーハ', 'Effect Monster', 'Reptile', 'DARK', 4, 1500, 1700, '这个卡名的①②的效果1回合各能使用1次。 ①：这张卡从场上送去墓地的场合或者从墓地的特殊召唤成功的场合才能发动。对方从卡组抽1张，自己从卡组把「溟界之漠-佐哈」以外的1只「溟界」怪兽加入手卡。那之后，双方玩家选1张手卡送去墓地。 ②：这张卡在墓地存在的场合，把1张手卡送去墓地才能发动。这张卡加入手卡。'),
(16268841, 'Zolga', '卓尔加', 'ゾルガ', 'Effect Monster', 'Fairy', 'EARTH', 4, 1700, 1200, '①：这张卡为上级召唤而被解放的场合发动。自己回复2000基本分。'),
(31525442, 'Zolga the Prophet', '预见者 卓尔加', '予見者ゾルガ', 'Effect Monster', 'Fairy', 'EARTH', 4, 1700, 1200, '这个卡名的①②的效果1回合各能使用1次。 ①：自己场上有「预见者 卓尔加」以外的天使族·地属性怪兽存在的场合才能发动。这张卡从手卡特殊召唤。那之后，自己从自己以及对方的卡组上面各最多5张确认。 ②：把这张卡解放作召唤的怪兽的攻击宣言时，把墓地的这张卡除外才能发动。那只怪兽破坏，给与对方2000伤害。'),
(88001391, 'Zoma the Earthbound Spirit', '地缚死灵 佐玛', '地縛死霊ゾーマ', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '这个卡名的①②的效果1回合各能使用1次。 ①：这张卡发动后变成持有以下效果的效果怪兽（不死族·暗·4星·攻1800/守500）在怪兽区域特殊召唤（也当作陷阱卡使用）。 ●可以攻击的对方怪兽必须向这张卡作出攻击。 ②：这张卡的效果特殊召唤的这张卡被对方怪兽的攻击破坏的场合发动。给与对方让这张卡破坏的怪兽的原本攻击力2倍数值的伤害（最多3000）。'),
(79852326, 'Zoma the Spirit', '死灵佐玛', '死霊ゾーマ', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '①：这张卡发动后变成效果怪兽（不死族·暗·4星·攻1800/守500）在怪兽区域守备表示特殊召唤。这张卡也当作陷阱卡使用。 ②：这张卡的效果特殊召唤的这张卡被战斗破坏的场合发动。给与对方让这张卡破坏的怪兽的攻击力数值的伤害。'),
(43642620, 'Zombie Mammoth', '猛犸僵尸', 'マンモス・ゾンビ', 'Effect Monster', 'Zombie', 'EARTH', 4, 1900, NULL, '自己墓地没有不死族怪兽存在的场合，这张卡破坏。场上表侧表示存在的这张卡被破坏的场合，给与那个时候的控制者这张卡的原本攻击力数值的伤害。'),
(17259470, 'Zombie Master', '僵尸主宰者', 'ゾンビ・マスター', 'Effect Monster', 'Zombie', 'DARK', 4, 1800, NULL, '①：1回合1次，从手卡把1只怪兽送去墓地，以自己或者对方的墓地1只4星以下的不死族怪兽为对象才能发动。那只不死族怪兽特殊召唤。这个效果在这张卡在怪兽区域表侧表示存在的场合才能发动和处理。'),
(300104001, 'Zombie Master (Skill Card)', NULL, NULL, 'Skill Card', 'Bonz', NULL, NULL, NULL, NULL, NULL),
(38363525, 'Zombie Necronize', '不死尸化', 'アンデット・ネクロナイズ', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的①②的效果1回合只能有1次使用其中任意1个。 ①：场上有5星以上的不死族怪兽存在的场合，以对方场上1只怪兽为对象才能发动。那只怪兽的控制权直到结束阶段得到。 ②：这张卡在墓地存在的场合才能发动。选除外的1只自己的不死族怪兽回到卡组，这张卡在自己场上盖放。这个效果盖放的这张卡从场上离开的场合除外。'),
(65357623, 'Zombie Power Struggle', '不死斗争', 'アンデット・ストラグル', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '这个卡名的②的效果1回合只能使用1次。 ①：以场上1只不死族怪兽为对象才能发动。直到回合结束时，那只怪兽的攻击力上升1000或者下降1000。 ②：这张卡在墓地存在的场合，自己主要阶段才能发动。选除外的1只自己的不死族怪兽回到卡组，这张卡在自己场上盖放。这个效果盖放的这张卡从场上离开的场合除外。'),
(19942835, 'Zombie Reborn', '不死苏生', 'アンデット・リボーン', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的①②的效果1回合只能有1次使用其中任意1个。 ①：以自己或者对方的墓地1只不死族怪兽为对象才能发动。从自己的卡组·额外卡组把1只那只怪兽的同名怪兽除外，作为对象的怪兽在自己场上特殊召唤。 ②：这张卡在墓地存在的场合才能发动。选除外的1只自己的不死族怪兽回到卡组，这张卡在自己场上盖放。这个效果盖放的这张卡从场上离开的场合除外。'),
(47693640, 'Zombie Tiger', '僵尸虎', 'ゾンビタイガー', 'Union Effect Monster', 'Zombie', 'EARTH', 3, 1400, 1600, '1回合只有1次在自己的主要阶段可以当作装备卡使用给自己的「腐朽的武将」装备，或者把装备解除以表侧攻击表示特殊召唤。只在这个效果当作装备卡使用时，装备怪兽的攻击力·守备力上升500点。装备怪兽每次战斗破坏对方怪兽时，对方随机丢弃1张手卡。（1只怪兽可以装备的同盟最多1张。装备怪兽被战斗破坏的场合，作为代替把这张卡破坏。）'),
(31339260, 'Zombie Warrior', '不死战士', 'アンデット・ウォーリアー', 'Fusion Monster', 'Zombie', 'DARK', 3, 1200, 900, '「白骨」＋「格斗战士 阿提米特」'),
(4064256, 'Zombie World', '不死世界', 'アンデットワールド', 'Spell Card', 'Field', NULL, NULL, NULL, NULL, '①：场上的表侧表示怪兽以及墓地的怪兽变成不死族。 ②：双方不是不死族怪兽不能上级召唤。'),
(81616639, 'Zombina', '僵尸女孩', 'ゾンビーナ', 'Effect Monster', 'Zombie', 'EARTH', 4, 1400, 1500, '①：这张卡被对方破坏的场合，以「僵尸女孩」以外的自己墓地1只4星以下的怪兽为对象才能发动。那只怪兽特殊召唤。'),
(14575467, 'Zombino', '僵尸男孩', 'ゾンビーノ', 'Normal Monster', 'Zombie', 'EARTH', 4, 2000, NULL, '两个人 特别要好 死了也相随 活了也相伴 不离不弃  所以 两个人永远 都不会再次相见'),
(27971137, 'Zombowwow', '腐乱犬', '腐乱犬', 'Effect Monster', 'Zombie', 'DARK', 2, 1000, 1000, '这张卡的攻击力在每次这张卡攻击宣言上升500。此外，场上的这张卡被破坏送去墓地的场合，可以从卡组把1只攻击力和守备力是0的1星怪兽特殊召唤。这个效果特殊召唤的怪兽的效果无效化，下次的自己的结束阶段时破坏。'),
(88472456, 'Zombyra the Dark', '暗黑英雄 尸魔侠', 'ダーク・ヒーロー ゾンバイア', 'Effect Monster', 'Warrior', 'DARK', 4, 2100, 500, '①：这张卡不能直接攻击。 ②：这张卡战斗破坏怪兽的场合发动。这张卡的攻击力下降200。'),
(86100785, 'Zone Eater', '区域吞噬者', 'ゾーン・イーター', 'Effect Monster', 'Aqua', 'WATER', 1, 250, 200, '受到「区域吞噬者」攻击的怪兽，5回合后被破坏。'),
(46060017, 'Zoodiac Barrage', '十二兽的会局', '十二獣の会局', 'Spell Card', 'Continuous', NULL, NULL, NULL, NULL, '「十二兽的会局」的①的效果1回合只能使用1次。 ①：以自己场上1张表侧表示的卡为对象才能把这个效果发动。那张卡破坏，从卡组把1只「十二兽」怪兽特殊召唤。 ②：这张卡被效果破坏送去墓地的场合，以自己场上1只「十二兽」超量怪兽为对象才能发动。把墓地的这张卡在那只超量怪兽下面重叠作为超量素材。'),
(74393852, 'Zoodiac Boarbow', '十二兽 亥弓', '十二獣ワイルドボウ', 'XYZ Monster', 'Beast-Warrior', 'EARTH', 4, -1, -1, '4星怪兽×5 「十二兽 猪弓」1回合1次也能在同名卡以外的自己场上的「十二兽」怪兽上面重叠来超量召唤。 ①：这张卡的攻击力·守备力上升这张卡作为超量素材中的「十二兽」怪兽的各自数值。 ②：这张卡可以向对方直接攻击。 ③：持有的超量素材数量是12以上的这张卡给与对方战斗伤害时才能发动。对方的手卡·场上的卡全部送去墓地，那之后，这张卡变成守备表示。'),
(85115440, 'Zoodiac Broadbull', '十二兽 丑斧', '十二獣ブルホーン', 'XYZ Monster', 'Beast-Warrior', 'EARTH', 4, -1, -1, '4星怪兽×2 「十二兽 牛犄」1回合1次也能在同名卡以外的自己场上的「十二兽」怪兽上面重叠来超量召唤。 ①：这张卡的攻击力·守备力上升这张卡作为超量素材中的「十二兽」怪兽的各自数值。 ②：1回合1次，把这张卡1个超量素材取除才能发动。从卡组把1只可以通常召唤的兽战士族怪兽加入手卡。'),
(4367330, 'Zoodiac Bunnyblast', '十二兽 卯铳', '十二獣ラビーナ', 'Effect Monster', 'Beast-Warrior', 'EARTH', 4, 800, 800, '①：这张卡被战斗·效果破坏的场合，以「十二兽 兔铳」以外的自己墓地1张「十二兽」卡为对象才能发动。那张卡加入手卡。 ②：持有这张卡作为素材中的原本种族是兽战士族的超量怪兽得到以下效果。 ●这张卡为对象的对方的魔法卡的效果发动时，把这张卡1个超量素材取除才能发动。那个发动无效。'),
(41375811, 'Zoodiac Chakanine', '十二兽 戌环', '十二獣ライカ', 'XYZ Monster', 'Beast-Warrior', 'EARTH', 4, -1, -1, '4星怪兽×2只以上 「十二兽 狗环」1回合1次也能在同名卡以外的自己场上的「十二兽」怪兽上面重叠来超量召唤。 ①：这张卡的攻击力·守备力上升这张卡作为超量素材中的「十二兽」怪兽的各自数值。 ②：1回合1次，把这张卡1个超量素材取除，以自己墓地1只「十二兽」怪兽为对象才能发动。那只怪兽特殊召唤。这个效果特殊召唤的怪兽在这个回合效果无效化，不能作为超量召唤的素材。'),
(73881652, 'Zoodiac Combo', '十二兽的方合', '十二獣の方合', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '①：以自己场上1只「十二兽」超量怪兽为对象才能发动。从卡组选1只「十二兽」怪兽在那只超量怪兽下面重叠作为超量素材。 ②：把墓地的这张卡除外，以自己墓地5张「十二兽」卡为对象才能发动（同名卡最多1张）。那5张卡加入卡组洗切。那之后，自己从卡组抽1张。这个效果在这张卡送去墓地的回合不能发动。'),
(48905153, 'Zoodiac Drident', '十二兽 辰枪', '十二獣ドランシア', 'XYZ Monster', 'Beast-Warrior', 'EARTH', 4, -1, -1, '4星怪兽×4 「十二兽 龙枪」1回合1次也能在同名卡以外的自己场上的「十二兽」怪兽上面重叠来超量召唤。 ①：这张卡的攻击力·守备力上升这张卡作为超量素材中的「十二兽」怪兽的各自数值。 ②：自己·对方回合1次，把这张卡1个超量素材取除，以场上1张表侧表示卡为对象才能发动。那张卡破坏。'),
(98918572, 'Zoodiac Gathering', '十二兽的相克', '十二獣の相剋', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '「十二兽的相克」的①的效果1回合只能使用1次。 ①：只要这张卡在魔法与陷阱区域存在，自己的「十二兽」超量怪兽把超量素材取除来让效果发动的场合，取除的超量素材可以从自己场上的其他的超量怪兽取除。 ②：把墓地的这张卡除外，以自己场上2只「十二兽」超量怪兽为对象才能发动。作为对象的怪兽中的1只在另1只下面重叠作为超量素材。'),
(14970113, 'Zoodiac Hammerkong', '十二兽 申锤', '十二獣ハマーコング', 'XYZ Monster', 'Beast-Warrior', 'EARTH', 4, -1, -1, '4星怪兽×3只以上 「十二兽 猴槌」1回合1次也能在同名卡以外的自己场上的「十二兽」怪兽上面重叠来超量召唤。 ①：这张卡的攻击力·守备力上升这张卡作为超量素材中的「十二兽」怪兽的各自数值。 ②：只要持有超量素材的这张卡在怪兽区域存在，对方不能把这张卡以外的场上的「十二兽」怪兽作为效果的对象。 ③：自己·对方的结束阶段发动。这张卡1个超量素材取除。'),
(20155904, 'Zoodiac Kataroost', '十二兽 酉刃', '十二獣クックル', 'Effect Monster', 'Beast-Warrior', 'EARTH', 4, 800, 1200, '①：这张卡被战斗·效果破坏的场合，以「十二兽 鸡拳」以外的自己墓地1张「十二兽」卡为对象才能发动。那张卡回到卡组。 ②：持有这张卡作为素材中的原本种族是兽战士族的超量怪兽得到以下效果。 ●这张卡为对象的对方怪兽的效果发动时，把这张卡1个超量素材取除才能发动。那个发动无效。'),
(4145852, 'Zoodiac Ramram', '十二兽 未盾', '十二獣ラム', 'Effect Monster', 'Beast-Warrior', 'EARTH', 4, 400, 2000, '①：这张卡被战斗·效果破坏的场合，以「十二兽 羊冲」以外的自己墓地1只「十二兽」怪兽为对象才能发动。那只怪兽特殊召唤。 ②：持有这张卡作为素材中的原本种族是兽战士族的超量怪兽得到以下效果。 ●这张卡为对象的对方的陷阱卡的效果发动时，把这张卡1个超量素材取除才能发动。那个发动无效。'),
(78872731, 'Zoodiac Ratpier', '十二兽 子骑', '十二獣モルモラット', 'Effect Monster', 'Beast-Warrior', 'EARTH', 4, NULL, NULL, '①：这张卡召唤成功的场合才能发动。从卡组把1张「十二兽」卡送去墓地。 ②：持有这张卡作为素材中的原本种族是兽战士族的超量怪兽得到以下效果。 ●1回合1次，把这张卡1个超量素材取除才能发动。从手卡·卡组把1只「十二兽 鼠骑」特殊召唤。'),
(77150143, 'Zoodiac Thoroughblade', '十二兽 午剑', '十二獣サラブレード', 'Effect Monster', 'Beast-Warrior', 'EARTH', 4, 1600, NULL, '①：这张卡召唤·特殊召唤成功的场合才能发动。从手卡丢弃1张「十二兽」卡，自己从卡组抽1张。 ②：持有这张卡作为素材中的原本种族是兽战士族的超量怪兽得到以下效果。 ●这张卡向守备表示怪兽攻击的场合，给与攻击力超过那个守备力的数值的战斗伤害。'),
(11510448, 'Zoodiac Tigermortar', '十二兽 寅炮', '十二獣タイグリス', 'XYZ Monster', 'Beast-Warrior', 'EARTH', 4, -1, -1, '4星怪兽×3 「十二兽 虎炮」1回合1次也能在同名卡以外的自己场上的「十二兽」怪兽上面重叠来超量召唤。 ①：这张卡的攻击力·守备力上升这张卡作为超量素材中的「十二兽」怪兽的各自数值。 ②：1回合1次，把这张卡1个超量素材取除，以自己场上1只超量怪兽和自己墓地1只「十二兽」怪兽为对象才能发动。那只「十二兽」怪兽在那只超量怪兽下面重叠作为超量素材。'),
(31755044, 'Zoodiac Whiptail', '十二兽 巳鞭', '十二獣ヴァイパー', 'Effect Monster', 'Beast-Warrior', 'EARTH', 4, 1200, 400, '①：以自己场上1只兽战士族超量怪兽为对象才能发动。把自己的手卡·场上的这张卡在那只怪兽下面重叠作为超量素材。这个效果在对方回合也能发动。 ②：持有这张卡作为素材中的原本种族是兽战士族的超量怪兽得到以下效果。 ●这张卡和对方怪兽进行战斗的伤害计算后发动。那只对方怪兽除外。'),
(95911373, 'Zoroa, the Magistus Conflagrant Calamity', '伟魔代蒙 绝火之琐罗亚', '絶火の魔神ゾロア', 'Synchro Monster', 'Spellcaster', 'FIRE', 8, 2900, 1500, '魔法师族调整＋调整以外的怪兽1只以上 这个卡名的③的效果1回合只能使用1次。 ①：这张卡同调召唤成功的场合才能发动。从额外卡组把1只「大贤者」怪兽当作装备卡使用给这张卡装备。 ②：对方不能把和自己的魔法与陷阱区域的「大贤者」怪兽卡相同种类（融合·同调·超量·连接）的怪兽的效果发动。 ③：以自己场上1张「大贤者」卡为对象才能发动。那张卡破坏，这张卡从墓地特殊召唤。'),
(36099130, 'Zoroa, the Magistus of Flame', '伟魔贤者 绝火之琐罗亚', '絶火の大賢者ゾロア', 'Tuner Monster', 'Spellcaster', 'FIRE', 4, 1500, 1500, '这个卡名的①②的效果1回合各能使用1次。 ①：以自己场上1只「大贤者」怪兽为对象才能发动。从额外卡组把1只「大贤者」怪兽当作装备魔法卡使用给作为对象的怪兽装备。 ②：让这张卡把「大贤者」怪兽卡装备的场合才能发动。从自己的手卡·墓地把「绝火之大贤者 琐罗亚」以外的1只魔法师族·4星怪兽守备表示特殊召唤。这个效果特殊召唤的怪兽的效果无效化。'),
(37260677, 'Zoroa, the Magistus Verethragna', '龙王绝火 伟魔琐罗亚', '竜王絶火ゾロア', 'Fusion Monster', 'Spellcaster', 'FIRE', 8, 2900, 2900, '「大贤者」怪兽＋融合·同调·超量·连接怪兽 这个卡名的①②的效果1回合各能使用1次。 ①：以自己墓地或对方场上1只效果怪兽为对象才能发动。那只效果怪兽当作装备魔法卡使用给这张卡装备。 ②：怪兽的效果发动时，把自己场上1张表侧表示的「大贤者」怪兽卡送去墓地才能发动。那个效果无效。那之后，可以把对方场上1张卡破坏。'),
(68258355, 'ZS - Armed Sage', 'ZEXAL从者－武装贤者', 'ZS－武装賢者', 'Effect Monster', 'Warrior', 'LIGHT', 4, 300, 900, '这个卡名的②的效果1回合只能使用1次。 ①：自己场上的怪兽只有「异热同心从者-武装贤者」以外的4星怪兽1只的场合，这张卡可以从手卡特殊召唤。 ②：场上的这张卡为素材作超量召唤的「希望皇 霍普」怪兽得到以下效果。 ●这张卡超量召唤的场合才能发动。从卡组把1只「异热同心武器」怪兽加入手卡。'),
(4647954, 'ZS - Ascended Sage', 'ZEXAL从者－升华贤者', 'ZS－昇華賢者', 'Effect Monster', 'Warrior', 'LIGHT', 4, 900, 300, '这个卡名的②的效果1回合只能使用1次。 ①：自己场上没有卡存在的场合，这张卡可以从手卡特殊召唤。 ②：场上的这张卡为素材作超量召唤的「希望皇 霍普」怪兽得到以下效果。 ●这张卡超量召唤的场合才能发动。从卡组把1张「升阶魔法」通常魔法卡加入手卡。'),
(32281491, 'ZS - Ouroboros Sage', '异热同心从者-双头龙贤者', 'ZS－双頭龍賢者', 'Effect Monster', 'Warrior', 'DARK', 3, 600, NULL, '①：这张卡召唤成功时才能发动。从自己墓地选1只光属性以外的「No.」怪兽效果无效特殊召唤，从自己场上把这张卡和1只「希望皇 霍普」怪兽各当作攻击力上升1700的装备卡使用给那只特殊召唤的怪兽装备。这个回合，自己只能有1次攻击宣言。 ②：用这张卡的效果把这张卡装备的怪兽向对方怪兽攻击宣言时才能发动。那只攻击怪兽攻击力变成2倍并在结束阶段破坏。'),
(31123642, 'ZS - Utopic Sage', 'ZEXAL从者－霍普贤者', 'ZS－希望賢者', 'XYZ Monster', 'Warrior', 'LIGHT', 4, 2000, 2500, '4星怪兽×2 这个卡名的①的效果1回合只能使用1次。 ①：把这张卡2个超量素材取除才能发动。从卡组把1只「异热同心武器」怪兽或者「异热同心从者」怪兽特殊召唤。这个效果的发动后，直到回合结束时自己不是超量怪兽不能从额外卡组特殊召唤，不用「No.」怪兽不能攻击。 ②：除「异热同心从者-希望贤者」外的自己场上的原本属性是光属性的「霍普」超量怪兽被战斗·效果破坏的场合，可以作为代替把场上·墓地的这张卡除外。'),
(51865604, 'ZS - Vanish Sage', 'ZEXAL从者－幻影贤者', 'ZS－幻影賢者', 'Effect Monster', 'Warrior', 'LIGHT', 1, 500, 100, '这个卡名的①②的效果1回合只能有1次使用其中任意1个。 ①：自己场上有「希望皇 霍普」怪兽存在的场合才能发动。自己从卡组抽1张。 ②：自己场上的怪兽在战斗阶段中被除外的场合，以那之内的1只为对象，把这张卡从场上除外才能发动。作为对象的怪兽在自己场上特殊召唤，对方场上有攻击力3000以下的怪兽存在的场合，选那之内的1只除外。'),
(57036718, 'Zubaba Buster', '刷拉拉破坏者', 'ズバババスター', 'Effect Monster', 'Warrior', 'EARTH', 3, 1800, 600, '这张卡给与对方基本分战斗伤害的伤害步骤结束时，场上表侧表示存在的1只攻击力最低的怪兽破坏，这张卡的攻击力下降800。'),
(31563350, 'Zubaba General', '刷拉拉将军', 'ズババジェネラル', 'XYZ Monster', 'Warrior', 'EARTH', 4, 2000, 1000, '4星怪兽×2 1回合1次，把这张卡1个超量素材取除才能发动。从手卡把1只战士族怪兽当作装备卡使用给这张卡装备。这张卡的攻击力上升这个效果装备的怪兽的攻击力数值。'),
(97896503, 'Zubaba Knight', '刷拉拉骑士', 'ズババナイト', 'Effect Monster', 'Warrior', 'EARTH', 3, 1600, 900, '①：这张卡向表侧守备表示怪兽攻击的伤害步骤开始时发动。那只怪兽破坏。'),
(62006866, 'Zubababa Knight', '刷拉拉拉骑士', 'ズバババナイト', 'Effect Monster', 'Warrior', 'EARTH', 3, 1600, 900, '这个卡名的①②的效果1回合各能使用1次。 ①：这张卡召唤·特殊召唤的场合，可以从以下效果选择1个发动。 ●从卡组把「刷拉拉拉骑士」以外的1只「刷拉拉」怪兽加入手卡。这张卡的等级变成和这个效果加入手卡的怪兽相同。 ●对方场上1只4星以下的守备表示怪兽破坏。 ②：超量素材的这张卡为让超量怪兽的效果发动而被取除的场合才能发动。从卡组把1只「我我我」怪兽加入手卡。'),
(23720856, 'Zubababancho Gagagacoat', '刷拉拉番长－我我我外套', 'ズバババンチョー－GC', 'Effect Monster', 'Warrior', 'EARTH', 4, 1800, 100, '这个卡名的①②的效果1回合各能使用1次。 ①：这张卡在手卡存在，自己场上有「刷拉拉番长-我我我外套」以外的，「刷拉拉」怪兽或「我我我」怪兽存在的场合才能发动。这张卡特殊召唤。 ②：以自己墓地1只「隆隆隆」怪兽或「怒怒怒」怪兽为对象才能发动。那只怪兽特殊召唤。这个效果的发动后，直到回合结束时自己不是超量怪兽不能从额外卡组特殊召唤。'),
(43256007, 'Zuijin of the Ice Barrier', '冰结界的随身', '氷結界の随身', 'Effect Monster', 'Warrior', 'WATER', 2, 500, 300, '这个卡名的①②的效果1回合各能使用1次。 ①：把这张卡解放才能发动。从手卡把1只5星以上的「冰结界」怪兽特殊召唤。 ②：这个回合没有送去墓地的这张卡在墓地存在的场合，以自己场上1只3星以上的水属性怪兽为对象才能发动。那只怪兽的等级下降2星，这张卡特殊召唤。这个效果特殊召唤的这张卡从场上离开的场合除外。'),
(7459013, 'Zure, Knight of Dark World', '暗黑界的骑士 祖尔', '暗黒界の騎士 ズール', 'Normal Monster', 'Fiend', 'DARK', 4, 1800, 1500, '暗黑界里其名无人不知的崇高骑士。绝对不会对弱者出手。'),
(67547370, 'Zushin the Sleeping Giant', '睡巨人 咕咚', '眠れる巨人ズシン', 'Effect Monster', 'Warrior', 'EARTH', 10, NULL, NULL, '这张卡不能通常召唤。把有咕咚指示物10个放置的1只自己怪兽解放的场合才能特殊召唤。 ①：1回合1次，把手卡的这张卡直到回合结束时给对方观看，以自己场上1只1星通常怪兽为对象才能发动。给那只怪兽放置1个咕咚指示物。 ②：这张卡不受其他卡的效果影响。 ③：这张卡和怪兽进行战斗的伤害计算时发动。这张卡的攻击力·守备力只在伤害计算时变成那只怪兽的攻击力＋1000的数值。'),
(24454387, 'Zuttomozaurus', '永久友伴恐龙', 'ズットモザウルス', 'Effect Monster', 'Dinosaur', 'EARTH', 2, 500, 400, '这个卡名的②的效果1回合只能使用1次。 ①：只要自己场上有其他的恐龙族怪兽存在，对方怪兽不能选择这张卡作为攻击对象。 ②：以自己场上1张其他卡为对象才能发动。那张卡破坏。'),
(40941889, 'ZW - Asura Strike', 'ZEXAL兵器－阿修罗副腕', 'ZW－阿修羅副腕', 'Effect Monster', 'Fairy', 'FIRE', 4, 1000, 1000, '①：「异热同心武器-阿修罗副腕」在自己场上只能有1张表侧表示存在。 ②：以自己场上1只「希望皇 霍普」怪兽为对象才能发动。从自己的手卡·场上把这张卡当作攻击力上升1000的装备卡使用给那只自己的「希望皇 霍普」怪兽装备。 ③：这张卡装备中的场合，装备怪兽可以向对方场上的全部怪兽各作1次攻击。'),
(2896663, 'ZW - Dragonic Halberd', 'ZEXAL兵器－弩级兵装龙王戟', 'ZW－弩級兵装竜王戟', 'XYZ Monster', 'Dragon', 'DARK', 5, 3000, 1200, '5星怪兽×2 ①：这张卡不能直接攻击。 ②：1回合1次，把这张卡1个超量素材取除才能发动。从卡组把1张「异热同心」魔法·陷阱卡加入手卡。 ③：以自己场上1只「希望皇 霍普」怪兽为对象才能发动。自己场上的这张卡当作攻击力上升3000的装备卡使用给那只怪兽装备。 ④：装备怪兽战斗破坏怪兽时才能发动。选给装备怪兽装备的「异热同心武器」怪兽卡任意数量特殊召唤。'),
(29353756, 'ZW - Eagle Claw', 'ZEXAL兵器－荒鹫激神爪', 'ZW－荒鷲激神爪', 'Effect Monster', 'Winged Beast', 'WIND', 5, 2000, 1200, '①：「异热同心武器-荒鹫激神爪」在自己场上只能有1张表侧表示存在。 ②：自己基本分比对方少2000以上的场合，这张卡可以从手卡特殊召唤。 ③：以自己场上1只「希望皇 霍普」怪兽为对象才能发动。自己场上的这张卡当作攻击力上升2000的装备卡使用给那只自己的「希望皇 霍普」怪兽装备。 ④：这张卡装备中的场合，1回合1次，对方场上发动的陷阱卡的效果无效。'),
(60992364, 'ZW - Leo Arms', 'ZEXAL兵器－兽王狮子武装', 'ZW－獣王獅子武装', 'XYZ Monster', 'Beast', 'LIGHT', 5, 3000, 1200, '5星怪兽×2 这张卡不能直接攻击。1回合1次，可以通过把这张卡1个超量素材取除，从卡组把1只名字带有「异热同心武器」的怪兽加入手卡。此外，场上的这只怪兽可以当作攻击力上升3000的装备卡使用给自己场上的名字带有「希望皇 霍普」的怪兽装备。装备怪兽攻击过的战斗阶段中，可以通过把装备的这张卡送去墓地，那次战斗阶段中，装备怪兽向对方怪兽只再1次可以攻击。'),
(45082499, 'ZW - Lightning Blade', 'ZEXAL兵器－雷神猛虎剑', 'ZW－雷神猛虎剣', 'Effect Monster', 'Beast', 'LIGHT', 5, 1200, 2000, '①：「异热同心武器-雷神猛虎剑」在自己场上只能有1张表侧表示存在。 ②：以自己场上1只「希望皇 霍普」怪兽为对象才能发动。从自己的手卡·场上把这张卡当作攻击力上升1200的装备卡使用给那只自己的「希望皇 霍普」怪兽装备。 ③：这张卡装备中的场合，自己场上的「异热同心武器」卡不会被对方的效果破坏。 ④：装备怪兽被效果破坏的场合，作为代替把这张卡破坏。'),
(32164201, 'ZW - Pegasus Twin Saber', 'ZEXAL兵器－天马双翼军刀', 'ZW－天馬双翼剣', 'Effect Monster', 'Beast', 'LIGHT', 5, 1000, 2100, '①：「异热同心武器-天马双翼剑」在自己场上只能有1张表侧表示存在。 ②：自己基本分比对方少2000以上的场合，这张卡可以从手卡特殊召唤。 ③：以自己场上1只「希望皇 霍普」怪兽为对象才能发动。自己场上的这张卡当作攻击力上升1000的装备魔法卡使用给那只怪兽装备。 ④：这张卡装备中的场合，1回合1次，由对方在场上发动的怪兽的效果的处理时，可以把那个效果无效。'),
(87008374, 'ZW - Phoenix Bow', '异热同心武器-不死鸟弩弓', 'ZW－不死鳥弩弓', 'Effect Monster', 'Winged Beast', 'FIRE', 3, 1100, NULL, '这张卡可以从手卡当作装备卡使用给自己场上的「混沌No.39 希望皇 霍普雷」装备。用这个效果把这张卡装备的怪兽的攻击力上升1100。此外，装备怪兽战斗破坏对方怪兽时，给与对方基本分1000分伤害。「异热同心武器-不死鸟弩弓」在自己场上只能有1张表侧表示存在。'),
(2648201, 'ZW - Sleipnir Mail', '异热同心武器-极星神马圣铠', 'ZW－極星神馬聖鎧', 'Effect Monster', 'Beast', 'LIGHT', 4, 1000, 1000, '①：「异热同心武器-极星神马圣铠」在自己场上只能有1张表侧表示存在。 ②：以自己场上1只「希望皇 霍普」怪兽为对象才能发动。从自己的手卡·场上把这张卡当作攻击力上升1000的装备卡使用给那只自己的「希望皇 霍普」怪兽装备。 ③：装备怪兽被对方破坏让这张卡被送去墓地时，以自己墓地1只「希望皇 霍普」怪兽为对象才能发动。那只怪兽特殊召唤。'),
(95886782, 'ZW - Sylphid Wing', '异热同心武器-天风精灵翼', 'ZW－天風精霊翼', 'Effect Monster', 'Beast', 'LIGHT', 4, 800, 1600, '①：「异热同心武器-天风精灵翼」在自己场上只能有1张表侧表示存在。 ②：以自己场上1只「希望皇 霍普」怪兽为对象才能发动。从自己的手卡·场上把这张卡当作攻击力上升800的装备卡使用给那只怪兽装备。 ③：1回合1次，对方发动的效果让怪兽特殊召唤的场合才能发动。装备怪兽的攻击力上升1600。 ④：装备怪兽把超量素材取除来让效果发动的场合，可以作为取除的1个超量素材的代替而把这张卡送去墓地。'),
(81471108, 'ZW - Tornado Bringer', 'ZEXAL兵器－风神云龙剑', 'ZW－風神雲龍剣', 'Effect Monster', 'Dragon', 'WIND', 5, 1300, 1800, '①：「异热同心武器-风神云龙剑」在自己场上只能有1张表侧表示存在。 ②：以自己场上1只「希望皇 霍普」怪兽为对象才能发动。从自己的手卡·场上把这张卡当作攻击力上升1300的装备卡使用给那只自己的「希望皇 霍普」怪兽装备。 ③：这张卡装备中的场合，对方不能把装备怪兽作为效果的对象。 ④：装备怪兽被战斗破坏的场合，作为代替把这张卡破坏。'),
(18865703, 'ZW - Ultimate Shield', '异热同心武器-玄武绝对圣盾', 'ZW－玄武絶対聖盾', 'Effect Monster', 'Aqua', 'EARTH', 4, NULL, 2000, '这张卡召唤·特殊召唤成功时，可以选择从游戏中除外的1只自己的超量怪兽表侧守备表示特殊召唤。此外，自己的主要阶段时，场上的这只怪兽可以当作守备力上升2000的装备卡使用给自己场上的名字带有「希望皇 霍普」的怪兽装备。「异热同心武器-玄武绝对圣盾」在自己场上只能有1张表侧表示存在。'),
(76080032, 'ZW - Unicorn Spear', 'ZEXAL兵器－一角兽皇枪', 'ZW－一角獣皇槍', 'Effect Monster', 'Beast', 'LIGHT', 4, 1900, NULL, '自己的主要阶段时，手卡的这张卡可以当作攻击力上升1900的装备卡使用给自己场上的「混沌No.39 希望皇 霍普雷」装备。装备怪兽和对方怪兽进行战斗的场合，只在战斗阶段内那只对方怪兽的效果无效化。「异热同心武器-独角兽皇枪」在自己场上只能有1张表侧表示存在。');